class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        MOD = 10**9 + 7
        m, n = len(grid), len(grid[0])
        dp = [[0] * 16 for _ in range(n)]
        dp[0][grid[0][0]] = 1
        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                v = grid[i][j]
                cur = [0] * 16
                for x in range(16):
                    nx = x ^ v
                    if j > 0:
                        cur[nx] = (cur[nx] + dp[j - 1][x]) % MOD
                    if i > 0:
                        cur[nx] = (cur[nx] + dp[j][x]) % MOD
                dp[j] = cur
        return dp[n - 1][k]

