class Solution {
public:
    int countPathsWithXorValue(vector<vector<int>>& grid, int k) {
        const long long MOD = 1e9 + 7;
        int m = grid.size(), n = grid[0].size();
        vector<array<long long,16>> dp(n);
        for (auto& a : dp) a.fill(0);
        dp[0][grid[0][0]] = 1;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) continue;
                int v = grid[i][j];
                array<long long,16> cur{};
                for (int x = 0; x < 16; x++) {
                    int nx = x ^ v;
                    if (j > 0) cur[nx] = (cur[nx] + dp[j - 1][x]) % MOD;
                    if (i > 0) cur[nx] = (cur[nx] + dp[j][x]) % MOD;
                }
                dp[j] = cur;
            }
        }
        return (int)dp[n - 1][k];
    }
};

