var countPathsWithXorValue = function(grid, k) {
    const MOD = 1e9 + 7;
    const m = grid.length, n = grid[0].length;
    const dp = Array.from({length: n}, () => new Array(16).fill(0));
    dp[0][grid[0][0]] = 1;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (i === 0 && j === 0) continue;
            const v = grid[i][j];
            const cur = new Array(16).fill(0);
            for (let x = 0; x < 16; x++) {
                const nx = x ^ v;
                if (j > 0) cur[nx] = (cur[nx] + dp[j - 1][x]) % MOD;
                if (i > 0) cur[nx] = (cur[nx] + dp[j][x]) % MOD;
            }
            dp[j] = cur;
        }
    }
    return dp[n - 1][k];
};
